/**
 * n8n Code node — wf2 step 1: build today's posting slots.
 * Output: one item per slot, each carrying scheduled_at + the breed/explore instruction.
 *
 * Rules encoded here:
 *  - 5 slots at the configured hours, each jittered ±18 min (never the same minute twice)
 *  - 8% chance a slot is skipped entirely — irregularity is an anti-detection feature
 *  - exactly 1 slot per day is forced to sell_intensity=0 (no link comment), and it is
 *    randomly placed, never always the same hour
 *  - slot order is consumed from next_cycle_plan (60% breed / 40% explore, pre-shuffled by wf4)
 */

const settings = $json.settings.posting;
const plan = $json.next_cycle_plan ?? [];
const tz = settings.timezone ?? 'Asia/Kuala_Lumpur';

const now = new Date();
const dayStart = new Date(now);
dayStart.setHours(0, 0, 0, 0);
dayStart.setDate(dayStart.getDate() + 1);   // generating for TOMORROW at 03:00

const slots = [];
const hours = settings.slot_hours;
const freeIdx = Math.floor(Math.random() * hours.length);   // which slot is non-commercial today

for (let i = 0; i < hours.length; i++) {
  if (Math.random() < (settings.skip_probability ?? 0.08)) continue;

  const jitter = Math.round((Math.random() * 2 - 1) * (settings.jitter_minutes ?? 18));
  const t = new Date(dayStart);
  t.setHours(hours[i], 0, 0, 0);
  t.setMinutes(t.getMinutes() + jitter);
  t.setSeconds(Math.floor(Math.random() * 60));

  const instruction = plan.shift() ?? { mode: 'explore' };

  slots.push({
    slot_index: i,
    scheduled_at: t.toISOString(),
    force_sell_intensity: i === freeIdx ? '0' : null,
    is_carousel: Math.random() < (settings.carousel_probability ?? 0.4),
    reply_delay_sec: Math.round(
      settings.reply_delay_range_sec[0] +
      Math.random() * (settings.reply_delay_range_sec[1] - settings.reply_delay_range_sec[0])
    ),
    plan: instruction,
    timezone: tz,
  });
}

// never leave a day with zero posts
if (slots.length === 0) {
  const t = new Date(dayStart); t.setHours(19, 12, 0, 0);
  slots.push({ slot_index: 3, scheduled_at: t.toISOString(), force_sell_intensity: null,
               is_carousel: false, reply_delay_sec: 70, plan: { mode: 'explore' }, timezone: tz });
}

return slots.map(s => ({ json: { ...s, remaining_plan: plan } }));

/**
 * n8n Code node — arm selection (wf2) and arm update (wf4).
 * Pure JS, no deps. Paste the relevant half into a Code node.
 *
 * Input for SELECT mode:
 *   $json.levers      : [{kind, code, brief, enabled}]
 *   $json.arm_stats      : [{scope, lever_kind, lever_code, alpha, beta, cooldown_until}]
 *   $json.context_weights: [{context_bucket, lever_kind, lever_code, alpha, beta, ...}]
 *   $json.products       : [{id, uid, name, ...}]
 *   $json.settings       : bandit settings object
 *   $json.scheduled_at   : optional slot timestamp; mapped to Work/Lunch/Evening/Late bucket
 *   $json.plan           : optional {mode:'breed', parent_post_id, keep:[], mutate:''}
 */

// ───────────────────────────── helpers

// Gamma(k,1) via Marsaglia-Tsang; needed for Beta sampling.
function gammaSample(k) {
  if (k < 1) return gammaSample(k + 1) * Math.pow(Math.random(), 1 / k);
  const d = k - 1 / 3, c = 1 / Math.sqrt(9 * d);
  for (;;) {
    let x, v;
    do { x = normalSample(); v = 1 + c * x; } while (v <= 0);
    v = v * v * v;
    const u = Math.random();
    if (u < 1 - 0.0331 * x * x * x * x) return d * v;
    if (Math.log(u) < 0.5 * x * x + d * (1 - v + Math.log(v))) return d * v;
  }
}
function normalSample() {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
function betaSample(a, b) {
  const x = gammaSample(a), y = gammaSample(b);
  return x / (x + y);
}


// ───────────────────────────── context helpers (2026 Threads)

const CONTEXT_BUCKETS = [
  { code: 'Late_Night_Impulse', start: 22, end: 6 },  // 22:00-05:59 (wraps midnight)
  { code: 'Work_Focus',         start: 6, end: 12 },  // 06:00-11:59
  { code: 'Lunch_Scroll',       start: 12, end: 15 }, // 12:00-14:59
  { code: 'Evening_Relax',      start: 15, end: 22 }, // 15:00-21:59
];

const DEFAULT_CONTEXT_TONE_PRIORS = {
  Work_Focus: {
    // Office/commute mode: compressed attention, lower tolerance for loud selling.
    minimal: { alpha: 2.6, beta: 1.4 },
    deadpan: { alpha: 2.4, beta: 1.5 },
    gaul: { alpha: 1.2, beta: 1.8 },
    chaotic: { alpha: 1.0, beta: 2.0 },
  },
  Lunch_Scroll: {
    gaul: { alpha: 2.0, beta: 1.5 },
    minimal: { alpha: 1.8, beta: 1.6 },
    deadpan: { alpha: 1.6, beta: 1.7 },
  },
  Evening_Relax: {
    // After work, Threads rewards personality and conversational mess more often.
    chaotic: { alpha: 2.7, beta: 1.3 },
    gaul: { alpha: 2.5, beta: 1.4 },
    enthusiast: { alpha: 1.8, beta: 1.6 },
    minimal: { alpha: 1.2, beta: 1.9 },
    deadpan: { alpha: 1.3, beta: 1.8 },
  },
  Late_Night_Impulse: {
    chaotic: { alpha: 2.2, beta: 1.5 },
    gaul: { alpha: 2.0, beta: 1.5 },
    deadpan: { alpha: 1.7, beta: 1.7 },
  },
};

function hourInTimezone(date, timezone) {
  const d = date ? new Date(date) : new Date();
  if (!Number.isFinite(d.getTime())) return new Date().getHours();
  if (!timezone) return d.getHours();
  try {
    const parts = new Intl.DateTimeFormat('en-US', { hour: '2-digit', hour12: false, timeZone: timezone }).formatToParts(d);
    return Number(parts.find(p => p.type === 'hour')?.value ?? d.getHours()) % 24;
  } catch {
    return d.getHours();
  }
}

function contextBucketForHour(hour) {
  const h = ((Number(hour) % 24) + 24) % 24;
  return CONTEXT_BUCKETS.find(b => (
    b.start < b.end ? (h >= b.start && h < b.end) : (h >= b.start || h < b.end)
  ))?.code ?? 'Late_Night_Impulse';
}

function contextBucketForSlot({ scheduled_at, published_at, timezone } = {}) {
  return contextBucketForHour(hourInTimezone(scheduled_at ?? published_at, timezone));
}

function normalizeInput(input) {
  // n8n wf2 carries loaded config under cfg; standalone Code-node tests often pass top-level.
  const cfg = input.cfg ?? {};
  const settings = input.settings ?? {
    posting: cfg.posting ?? {},
    bandit: cfg.bandit ?? {},
    scoring: cfg.scoring ?? {},
    qa: cfg.qa ?? {},
    llm: cfg.llm ?? {},
  };
  return {
    ...cfg,
    ...input,
    levers: input.levers ?? cfg.levers ?? [],
    armStats: input.armStats ?? input.arm_stats ?? cfg.armStats ?? cfg.arm_stats ?? [],
    productStats: input.productStats ?? input.product_stats ?? cfg.productStats ?? cfg.product_stats ?? [],
    contextWeights: input.contextWeights ?? input.context_weights ?? cfg.contextWeights ?? cfg.context_weights ?? [],
    prevStats: input.prevStats ?? input.prev_arm_stats ?? input.armStats ?? input.arm_stats ?? cfg.prevStats ?? cfg.prev_arm_stats ?? [],
    prevContextWeights: input.prevContextWeights ?? input.prev_context_weights ?? input.contextWeights ?? input.context_weights ?? cfg.prevContextWeights ?? cfg.prev_context_weights ?? [],
    products: input.products ?? cfg.products ?? [],
    settings,
    plan: input.plan ?? cfg.plan ?? null,
    scheduled_at: input.scheduled_at ?? input.slot?.scheduled_at ?? null,
    timezone: input.timezone ?? input.slot?.timezone ?? settings.posting?.timezone ?? cfg.posting?.timezone,
  };
}

function contextStatKey(bucket, kind, code) {
  return `${bucket}|${kind}|${code}`;
}

function buildContextMap(contextWeights = []) {
  return new Map((contextWeights ?? []).map(w => [
    contextStatKey(w.context_bucket ?? w.bucket, w.lever_kind ?? 'tone', w.lever_code), w,
  ]));
}

function getContextPrior(contextMap, bucket, kind, code) {
  const stored = contextMap.get(contextStatKey(bucket, kind, code));
  if (stored) return { alpha: Number(stored.alpha) || 1, beta: Number(stored.beta) || 1, n: Number(stored.n) || 0 };
  if (kind === 'tone') return DEFAULT_CONTEXT_TONE_PRIORS[bucket]?.[code] ?? { alpha: 1, beta: 1, n: 0 };
  return { alpha: 1, beta: 1, n: 0 };
}

// ───────────────────────────── SELECT: pick one arm

/**
 * Thompson sampling over each lever independently, with epsilon-greedy exploration
 * and a product-scoped prior blended into the global prior.
 *
 * Why per-lever and not per-combo: at 5 posts/day you get 15 samples per cycle. A 6800-arm
 * combo space never converges. Marginal levers converge in ~5 cycles. Combos are only used
 * as a tie-breaker once combo_stats.n >= min_n_for_combo.
 */
function pickArm({ levers, armStats, contextWeights, productUid, settings, plan, scheduled_at, timezone, force_sell_intensity }) {
  const eps = settings.bandit?.epsilon ?? settings.epsilon ?? 0.25;
  const now = Date.now();
  const context_bucket = contextBucketForSlot({ scheduled_at, timezone: timezone ?? settings.posting?.timezone });

  const statKey = (scope, kind, code) => `${scope}|${kind}|${code}`;
  const stats = new Map((armStats ?? []).map(s => [statKey(s.scope, s.lever_kind, s.lever_code), s]));
  const contextMap = buildContextMap(contextWeights ?? []);

  // media_type is a real lever, but it is CONSTRAINED by what the product actually has.
  // A text-only product can never draw IMAGE; a product with images can still draw TEXT,
  // because a text post about a product you own is perfectly legitimate and often out-reaches
  // an image post on Threads. That asymmetry is deliberate.
  const kinds = ['format', 'angle', 'tone', 'sell_intensity', 'length_band', 'media_type'];
  const chosen = {};

  for (const kind of kinds) {
    // If breeding, some levers are inherited from the parent post.
    if (plan?.mode === 'breed' && plan.keep?.includes(kind)) {
      chosen[kind] = plan.parent[kind];
      continue;
    }

    let options = levers.filter(l => l.kind === kind && l.enabled);

    // Restrict media_type to what this product can physically produce.
    if (kind === 'media_type') {
      const n = plan?.imageCount ?? 0;
      const allowed = n === 0 ? ['TEXT'] : (n === 1 ? ['TEXT', 'IMAGE'] : ['TEXT', 'IMAGE', 'CAROUSEL']);
      options = options.filter(o => allowed.includes(o.code));
      // Products WITH images should still mostly use them — they were uploaded for a reason.
      // Cap pure-text at ~30% for image products so the bandit explores without overriding intent.
      if (n > 0 && options.length > 1 && Math.random() > 0.30) {
        options = options.filter(o => o.code !== 'TEXT');
      }
    }

    if (!options.length) throw new Error(`bandit select: no enabled options for ${kind}`);

    // drop arms in cooldown, unless that would leave nothing
    const live = options.filter(o => {
      const g = stats.get(statKey('global', kind, o.code));
      return !g?.cooldown_until || new Date(g.cooldown_until).getTime() < now;
    });
    if (live.length >= 2) options = live;

    if (Math.random() < eps) {
      // EXPLORE: uniform. Bias slightly toward least-sampled arm.
      options.sort((a, b) => {
        const na = stats.get(statKey('global', kind, a.code))?.alpha ?? 1;
        const nb = stats.get(statKey('global', kind, b.code))?.alpha ?? 1;
        const ca = getContextPrior(contextMap, context_bucket, kind, a.code);
        const cb = getContextPrior(contextMap, context_bucket, kind, b.code);
        const biasA = kind === 'tone' ? (Number(ca.alpha) / (Number(ca.alpha) + Number(ca.beta))) : 0.5;
        const biasB = kind === 'tone' ? (Number(cb.alpha) / (Number(cb.alpha) + Number(cb.beta))) : 0.5;
        return (na - biasA + Math.random() * 3) - (nb - biasB + Math.random() * 3);
      });
      chosen[kind] = options[0].code;
    } else {
      // EXPLOIT: Thompson sample. Product-scoped evidence still matters most, but tone
      // also gets a time-of-day context prior so the account does not speak the same way
      // during office focus and evening doomscroll windows.
      let best = null, bestDraw = -1;
      for (const o of options) {
        const g = stats.get(statKey('global', kind, o.code)) ?? { alpha: 1, beta: 1 };
        const p = stats.get(statKey(`product:${productUid}`, kind, o.code)) ?? { alpha: 1, beta: 1 };
        const c = getContextPrior(contextMap, context_bucket, kind, o.code);
        const hasContext = kind === 'tone';
        const a = hasContext
          ? 0.30 * Number(g.alpha) + 0.45 * Number(p.alpha) + 0.25 * Number(c.alpha)
          : 0.40 * Number(g.alpha) + 0.60 * Number(p.alpha);
        const b = hasContext
          ? 0.30 * Number(g.beta) + 0.45 * Number(p.beta) + 0.25 * Number(c.beta)
          : 0.40 * Number(g.beta) + 0.60 * Number(p.beta);
        const draw = betaSample(Math.max(a, 0.05), Math.max(b, 0.05));
        if (draw > bestDraw) { bestDraw = draw; best = o.code; }
      }
      chosen[kind] = best;
    }
  }

  // Hard constraints that override the bandit.
  // 1. scarcity angle requires real scarcity data on the product
  if (chosen.angle === 'scarcity' && !plan?.productHasScarcityData) chosen.angle = 'social_proof';
  // 2. micro length can't carry a long format
  if (chosen.length_band === 'micro' && ['flash_story', 'diary', 'before_after'].includes(chosen.format)) {
    chosen.length_band = 'mid';
  }
  // 3. minimal/deadpan tone forbids sell_intensity 2 (reads as spam)
  if (['minimal', 'deadpan'].includes(chosen.tone) && chosen.sell_intensity === '2') {
    chosen.sell_intensity = '1';
  }
  // 4. A text-only post has no image to hold the scroll, so micro length is a bad bet:
  //    two lines with no visual is the easiest thing in a feed to skip past.
  if (chosen.media_type === 'TEXT' && chosen.length_band === 'micro') {
    chosen.length_band = 'mid';
  }
  // 5. Slot planner can force a no-link post for account health. Never let the bandit override it.
  if (force_sell_intensity !== undefined && force_sell_intensity !== null && force_sell_intensity !== '') {
    chosen.sell_intensity = String(force_sell_intensity);
  }

  chosen.context_bucket = context_bucket;
  chosen.combo_key = [chosen.format, chosen.angle, chosen.tone,
                      chosen.sell_intensity, chosen.length_band, chosen.media_type].join('|');
  return chosen;
}

/** Product choice: Thompson over product-level reward, with forced rotation for new products. */
function pickProduct({ products, productStats, settings }) {
  products = products ?? [];
  productStats = productStats ?? [];
  if (!products.length) throw new Error('bandit select: no active products supplied');
  const fresh = products.filter(p => (p.posts_count ?? 0) < 3);
  if (fresh.length && Math.random() < 0.5) {
    // new products get guaranteed airtime before the bandit is allowed to judge them
    return fresh[Math.floor(Math.random() * fresh.length)];
  }
  let best = null, bestDraw = -1;
  for (const p of products) {
    const s = productStats.find(x => x.product_uid === p.uid) ?? { alpha: 1, beta: 1 };
    const draw = betaSample(Math.max(Number(s.alpha), 0.05), Math.max(Number(s.beta), 0.05));
    if (draw > bestDraw) { bestDraw = draw; best = p; }
  }
  return best;
}

// ───────────────────────────── UPDATE: after a cycle

/**
 * scores: [{post, final_score, verdict}]  where post has the lever fields.
 * Rewards are min-max normalized to [0,1] inside the cycle, then folded into Beta params.
 * Old evidence decays so the model tracks what the algorithm rewards *this month*.
 */
function updateArms({ scores, prevStats, settings }) {
  settings = settings.bandit ?? settings;
  const decay = settings.decay ?? 0.9;
  const key = (scope, kind, code) => `${scope}|${kind}|${code}`;
  const out = new Map();

  // start from decayed previous state
  for (const s of prevStats) {
    out.set(key(s.scope, s.lever_kind, s.lever_code), {
      scope: s.scope, lever_kind: s.lever_kind, lever_code: s.lever_code,
      n: Number(s.n) * decay,
      reward_sum: Number(s.reward_sum) * decay,
      alpha: 1 + (Number(s.alpha) - 1) * decay,
      beta: 1 + (Number(s.beta) - 1) * decay,
      cooldown_until: s.cooldown_until,
    });
  }

  const vals = scores.map(s => s.final_score);
  const min = Math.min(...vals), max = Math.max(...vals);
  const norm = v => (max === min ? 0.5 : (v - min) / (max - min));

  const kinds = ['format', 'angle', 'tone', 'sell_intensity', 'length_band', 'media_type'];
  for (const s of scores) {
    const r = norm(s.final_score);            // 0..1
    for (const kind of kinds) {
      const code = String(s.post[kind] ?? '');
      if (!code) continue;
      for (const scope of ['global', `product:${s.post.product_uid}`]) {
        const k = key(scope, kind, code);
        const cur = out.get(k) ?? { scope, lever_kind: kind, lever_code: code,
                                    n: 0, reward_sum: 0, alpha: 1, beta: 1, cooldown_until: null };
        cur.n += 1;
        cur.reward_sum += r;
        cur.alpha += r;                        // fractional Beta update
        cur.beta  += (1 - r);
        out.set(k, cur);
      }
    }
  }

  // cooldown the persistent losers (global scope only, and only with enough evidence)
  const coolDays = settings.loser_cooldown_days ?? 9;
  for (const kind of kinds) {
    const arms = [...out.values()].filter(a => a.scope === 'global' && a.lever_kind === kind && a.n >= 4);
    if (arms.length < 4) continue;
    arms.sort((a, b) => (a.reward_sum / a.n) - (b.reward_sum / b.n));
    const nLosers = Math.max(1, Math.floor(arms.length * (settings.loser_bottom_pct ?? 0.3)));
    for (let i = 0; i < nLosers; i++) {
      arms[i].cooldown_until = new Date(Date.now() + coolDays * 864e5).toISOString();
    }
  }
  return [...out.values()];
}


/** Contextual tone stats: one row per time bucket × tone. */
function updateContextWeights({ scores, prevContextWeights, settings }) {
  const banditSettings = settings.bandit ?? settings;
  const postingSettings = settings.posting ?? {};
  const decay = banditSettings.decay ?? 0.9;
  const out = new Map();

  for (const s of (prevContextWeights ?? [])) {
    const bucket = s.context_bucket ?? s.bucket;
    const kind = s.lever_kind ?? 'tone';
    const code = s.lever_code;
    if (!bucket || !code) continue;
    out.set(contextStatKey(bucket, kind, code), {
      context_bucket: bucket,
      lever_kind: kind,
      lever_code: code,
      n: Number(s.n) * decay,
      reward_sum: Number(s.reward_sum) * decay,
      alpha: 1 + (Number(s.alpha) - 1) * decay,
      beta: 1 + (Number(s.beta) - 1) * decay,
      cooldown_until: s.cooldown_until ?? null,
    });
  }

  const vals = (scores ?? []).map(s => s.final_score);
  const min = Math.min(...vals), max = Math.max(...vals);
  const norm = v => (max === min ? 0.5 : (v - min) / (max - min));

  for (const s of (scores ?? [])) {
    const code = String(s.post?.tone ?? '');
    if (!code) continue;
    const bucket = s.post?.context_bucket ?? contextBucketForSlot({
      published_at: s.post?.published_at,
      scheduled_at: s.post?.scheduled_at,
      timezone: s.post?.timezone ?? postingSettings.timezone,
    });
    const k = contextStatKey(bucket, 'tone', code);
    const r = norm(s.final_score);
    const cur = out.get(k) ?? { context_bucket: bucket, lever_kind: 'tone', lever_code: code,
                                n: 0, reward_sum: 0, alpha: 1, beta: 1, cooldown_until: null };
    cur.n += 1;
    cur.reward_sum += r;
    cur.alpha += r;
    cur.beta += (1 - r);
    out.set(k, cur);
  }

  return [...out.values()];
}

/** Choose which winning posts to breed from next cycle. */
function planNextCycle({ scores, settings }) {
  settings = settings.bandit ? { ...settings.posting, ...settings.bandit } : settings;
  const sorted = [...scores].sort((a, b) => b.final_score - a.final_score);
  const nWin = Math.max(1, Math.ceil(sorted.length * (settings.winner_top_pct ?? 0.2)));
  const winners = sorted.slice(0, nWin);
  const slots = (settings.posts_per_day ?? 5) * (settings.cycle_days ?? 3);
  const breedSlots = Math.round(slots * 0.6);

  const kinds = ['format', 'angle', 'tone', 'length_band'];
  const plan = [];
  for (let i = 0; i < breedSlots; i++) {
    const parent = winners[i % winners.length];
    const mutate = kinds[Math.floor(Math.random() * kinds.length)];
    plan.push({
      mode: 'breed',
      parent_post_id: parent.post.id,
      keep: kinds.filter(k => k !== mutate),
      mutate,
    });
  }
  while (plan.length < slots) plan.push({ mode: 'explore' });
  // shuffle so breeding isn't all front-loaded
  for (let i = plan.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [plan[i], plan[j]] = [plan[j], plan[i]];
  }
  return plan;
}

// ───────────────────────────── n8n entry point
// Set MODE via the node: 'select' | 'update' | 'plan'. If omitted, infer from payload shape.
const input = normalizeInput($json);
const MODE = $json.mode ?? (input.scores ? 'update' : 'select');
if (MODE === 'select') {
  const product = pickProduct(input);
  const arm = pickArm({ ...input, productUid: product.uid, plan: input.plan });
  return [{ json: { ...$json, product, ...arm } }];
}
if (MODE === 'update') {
  return [{ json: {
    ...$json,
    arms: updateArms(input),
    context_weights: updateContextWeights(input),
    plan: planNextCycle(input),
  } }];
}
return [{ json: { ...$json, plan: planNextCycle(input) } }];

/**
 * n8n Code node — wf2 persona calibration.
 *
 * Input:
 *   $json.cfg.persona_snippets : [{id, domain, title, register, tags, text}]
 *   $json.tone                 : selected tone code from bandit
 *   $json.product              : product object with category_hint / enrichment
 *
 * Output:
 *   Adds persona_snippets + persona_fragment for the writer prompt.
 *
 * The snippets are style/rhythm references only. They must never become facts in a product post.
 */

function shuffle(xs) {
  const a = [...xs];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function toneRegisters(tone) {
  return ({
    warm_sibling: ['reflective', 'conversational'],
    deadpan: ['neutral', 'informative'],
    minimal: ['neutral', 'informative'],
    gaul: ['conversational', 'neutral'],
    chaotic: ['conversational'],
    enthusiast: ['conversational', 'informative'],
    corporate_parody: ['formal', 'informative'],
  })[tone] ?? ['conversational', 'neutral', 'reflective'];
}

function clean(s) {
  return String(s ?? '').replace(/\s+/g, ' ').trim();
}

function categoryScore(snippet, product) {
  if (!product) return 0;
  const categoryText = String(
    product.category_hint || product.enrichment?.category || product.name || ''
  ).toLowerCase();

  const domain = String(snippet.domain || snippet.source_domain || '').toLowerCase();
  const text = String(snippet.text || '').toLowerCase();

  const techKeywords = ['tech', 'gadget', 'phone', 'laptop', 'wireless', 'usb', 'charger', 'audio', 'sound', 'camera', 'peranti', 'skrin', 'bateri', 'moniter', 'keyboard'];
  const lifestyleKeywords = ['rumah', 'dapur', 'baju', 'kasut', 'skin', 'beauty', 'mask', 'kain', 'makanan', 'decor', 'bilik', 'budak', 'anak', 'beg'];

  const isTechProduct = techKeywords.some(k => categoryText.includes(k));
  const isLifestyleProduct = lifestyleKeywords.some(k => categoryText.includes(k));

  if (isTechProduct && (domain.includes('amanz') || text.includes('peranti') || text.includes('spesifikasi'))) {
    return 3;
  }
  if (isLifestyleProduct && (domain.includes('iium') || domain.includes('facebook') || snippet.register === 'reflective')) {
    return 3;
  }
  return 0;
}

function pickPersonaSnippets(input) {
  const all = input.persona_snippets ?? input.cfg?.persona_snippets ?? [];
  if (!Array.isArray(all) || !all.length) return { persona_snippets: [], persona_fragment: '' };

  const preferred = toneRegisters(input.tone);
  const product = input.product || input.product_data || {};

  const ranked = all
    .map(s => {
      const cleanedText = clean(s.text);
      let score = preferred.includes(s.register) ? 2 : 0;
      score += categoryScore(s, product);
      return { ...s, text: cleanedText, score };
    })
    .filter(s => s.text.length >= 80 && s.text.length <= 750)
    .sort((a, b) => b.score - a.score || Math.random() - 0.5);

  const picked = shuffle(ranked.slice(0, 12)).slice(0, 3);
  if (!picked.length) return { persona_snippets: [], persona_fragment: '' };

  const lines = picked.map((s, i) => {
    const label = [s.register, s.domain || s.source_domain].filter(Boolean).join(' · ');
    return `${i + 1}. (${label}) ${s.text.slice(0, 520)}`;
  });

  return {
    persona_snippets: picked,
    persona_fragment: `\n### Persona calibration — Malaysian cadence references\nThese are NOT facts and NOT templates. Borrow only rhythm, sentence pressure, and Malay register. Do not copy wording, claims, religious advice, or topic.\n${lines.join('\n')}\n`,
  };
}

if (typeof $json !== 'undefined') {
  const picked = pickPersonaSnippets($json);
  return [{ json: { ...$json, ...picked } }];
}

if (typeof module !== 'undefined') {
  module.exports = { pickPersonaSnippets, toneRegisters, categoryScore };
}

/**
 * n8n Code node — wf2, runs after bandit.js picks the levers.
 * Selects 1-2 compatible techniques ("devices") to inject into the writer prompt,
 * and renders the prompt fragment.
 *
 * Also contains the wf4-side update function so techniques earn/lose weight exactly like levers.
 *
 * Input $json:
 *   techniques : rows from `techniques` WHERE enabled
 *   arm        : {format, angle, tone, sell_intensity, length_band}
 *   recent_technique_ids : ids used in the last 6 posts (avoid immediate repeats)
 *   mode       : 'select' | 'update'
 */

// Beta sampling (same as bandit.js — duplicated so each Code node is standalone)
function normalSample() {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
function gammaSample(k) {
  if (k < 1) return gammaSample(k + 1) * Math.pow(Math.random(), 1 / k);
  const d = k - 1 / 3, c = 1 / Math.sqrt(9 * d);
  for (;;) {
    let x, v;
    do { x = normalSample(); v = 1 + c * x; } while (v <= 0);
    v = v * v * v;
    const u = Math.random();
    if (u < 1 - 0.0331 * x ** 4) return d * v;
    if (Math.log(u) < 0.5 * x * x + d * (1 - v + Math.log(v))) return d * v;
  }
}
const betaSample = (a, b) => { const x = gammaSample(a), y = gammaSample(b); return x / (x + y); };

/**
 * Why max 2 devices:
 *   0 devices → the library does nothing, you wasted an afternoon
 *   1-2       → shapes the post without defining it
 *   3+        → the LLM produces a checklist-shaped post. It reads mechanical. This is the
 *               single fastest way to reintroduce the template smell you're trying to kill.
 * Empirically 2 is the ceiling for a <500 char post. Do not raise this.
 */
const MAX_DEVICES = 2;

function selectDevices({ techniques, arm, recent_technique_ids = [] }) {
  const now = Date.now();
  const intensity = Number(arm.sell_intensity);

  const compatible = techniques.filter(t => {
    if (!t.enabled) return false;
    if (t.cooldown_until && new Date(t.cooldown_until).getTime() > now) return false;
    if (t.type === 'anti_pattern') return false;         // those live in banned_phrases, not here
    // empty array = universal
    const okF = !t.compatible_formats?.length   || t.compatible_formats.includes(arm.format);
    const okT = !t.compatible_tones?.length     || t.compatible_tones.includes(arm.tone);
    const okI = !t.compatible_intensity?.length || t.compatible_intensity.includes(intensity);
    // A technique that leans on the photo ("make the object the grammatical subject") must
    // never fire on a text-only post — it would produce copy describing an image nobody sees.
    const okM = !t.compatible_media?.length || t.compatible_media.includes(arm.media_type);
    return okF && okT && okI && okM;
  });

  if (!compatible.length) return { devices: [], fragment: '' };

  // Don't reuse a technique from the last 6 posts unless the pool is tiny — same reason we
  // rotate images: repetition at the *device* level produces posts that rhyme with each other.
  const pool = compatible.filter(t => !recent_technique_ids.includes(t.id));
  const usable = pool.length >= 4 ? pool : compatible;

  // One device is always a hook/structure (shapes the post), the second is anything else
  // (adds texture). Two hooks fight each other for the opening line.
  const shapers = usable.filter(t => ['hook', 'structure'].includes(t.type));
  const texture = usable.filter(t => !['hook', 'structure'].includes(t.type));

  const draw = list => {
    let best = null, bestScore = -1;
    for (const t of list) {
      const a = Math.max(Number(t.alpha) || 1, 0.05);
      const b = Math.max(Number(t.beta) || 1, 0.05);
      let s = betaSample(a, b);
      // contested claims get an exploration bonus — settling an argument between two famous
      // copywriters with your own conversion data is worth spending slots on
      if (t.contested && Number(t.n) < 8) s += 0.15;
      // untested techniques get a small bonus so the library doesn't sit unused
      if (Number(t.n) < 2) s += 0.10;
      if (s > bestScore) { bestScore = s; best = t; }
    }
    return best;
  };

  const devices = [];
  if (shapers.length && Math.random() < 0.75) devices.push(draw(shapers));
  const remaining = texture.filter(t => !devices.includes(t));
  if (remaining.length && devices.length < MAX_DEVICES && Math.random() < 0.7) {
    devices.push(draw(remaining));
  }
  // 15% of posts get zero devices — a pure-bandit control group. Without this you can never
  // tell whether the Technique Library is helping at all.
  if (Math.random() < 0.15) devices.length = 0;

  const fragment = devices.length ? `
### Craft constraints for this post
Apply these invisibly. Never name them, never explain them, never let the reader detect a formula.
${devices.map(d => `- ${d.instruction}
  Like this: ${d.example_do}
  Not like this: ${d.example_dont}`).join('\n')}
` : '';

  return { devices, device_ids: devices.map(d => d.id), fragment, is_control: !devices.length };
}

/**
 * wf4 side: fold cycle scores back into technique alpha/beta.
 * Input: {scores:[{post_id, final_score, technique_ids:[]}], prev:[techniques rows], settings}
 */
function updateTechniques({ scores, prev, settings }) {
  const decay = settings.decay ?? 0.9;
  const vals = scores.map(s => s.final_score);
  const min = Math.min(...vals), max = Math.max(...vals);
  const norm = v => (max === min ? 0.5 : (v - min) / (max - min));

  const out = new Map(prev.map(t => [t.id, {
    id: t.id, code: t.code,
    n: Number(t.n) * decay,
    reward_sum: Number(t.reward_sum) * decay,
    alpha: 1 + (Number(t.alpha) - 1) * decay,
    beta: 1 + (Number(t.beta) - 1) * decay,
    cooldown_until: t.cooldown_until,
  }]));

  for (const s of scores) {
    const r = norm(s.final_score);
    for (const id of s.technique_ids ?? []) {
      const cur = out.get(id);
      if (!cur) continue;
      cur.n += 1; cur.reward_sum += r; cur.alpha += r; cur.beta += (1 - r);
    }
  }

  // Cool down techniques that have earned their verdict. Threshold is n >= 6 because a
  // technique appears in far fewer posts than a lever value — don't judge it on 2 samples.
  const arr = [...out.values()];
  const judged = arr.filter(t => t.n >= 6);
  if (judged.length >= 5) {
    judged.sort((a, b) => (a.reward_sum / a.n) - (b.reward_sum / b.n));
    const nCool = Math.max(1, Math.floor(judged.length * 0.25));
    for (let i = 0; i < nCool; i++) {
      judged[i].cooldown_until = new Date(Date.now() + 12 * 864e5).toISOString();
    }
  }
  return arr;
}

const MODE = $json.mode ?? 'select';
return MODE === 'select'
  ? [{ json: selectDevices($json) }]
  : [{ json: { techniques: updateTechniques($json) } }];

/**
 * n8n Code node — wf2 QA gate. Runs after the editor LLM pass, before INSERT.
 * Returns {pass, reasons[], cleaned} — on fail, wf2 loops back to the writer.
 *
 * This node is the entire defence against "AI template smell". Be aggressive here;
 * a regenerate costs 0.0002 USD, a templated post costs you reach for a day.
 *
 * Input $json:
 *   text            : the candidate post body
 *   embedding       : number[] of the candidate
 *   recent          : [{body, embedding}]  last 30 posts
 *   banned          : [{pattern, scope}]
 *   length_band     : 'micro'|'mid'|'long'
 *   tone            : lever code
 *   sell_intensity  : '0'|'1'|'2'
 *   product_details : string[]  the 5 concrete facts from enrichment
 *   settings        : qa settings
 */

const EMOJI_RE = /[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu;

function cosine(a, b) {
  if (!a || !b || a.length !== b.length) return 0;
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb) || 1);
}

// Jaccard on word 3-grams — catches "same skeleton, different nouns", which embeddings miss.
function shingleOverlap(a, b, n = 3) {
  const grams = t => {
    const w = t.toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(Boolean);
    const s = new Set();
    for (let i = 0; i + n <= w.length; i++) s.add(w.slice(i, i + n).join(' '));
    return s;
  };
  const A = grams(a), B = grams(b);
  if (!A.size || !B.size) return 0;
  let inter = 0;
  for (const g of A) if (B.has(g)) inter++;
  return inter / (A.size + B.size - inter);
}

function qa(input) {
  const cfg = input.settings;
  const reasons = [];
  let text = (input.text || '').trim();

  // strip anything the model wrapped around the copy
  text = text.replace(/^```[\w]*\n?|```$/g, '').trim();
  text = text.replace(/^["'“](.*)["'”]$/s, '$1').trim();
  text = text.replace(/^(Berikut|Here'?s|Copy:|Post:)\s*:?\s*/i, '').trim();

  // 1. hard length
  if (text.length > 500) reasons.push('over Threads 500 char limit');
  const bands = { micro: [1, 120], mid: [110, 270], long: [250, 480] };
  let [lo, hi] = bands[input.length_band] ?? [1, 480];
  // no image => the text has to carry the whole post, so raise the floor
  if (input.media_type === 'TEXT') lo = Math.max(lo, 90);
  if (text.length < lo || text.length > hi) {
    reasons.push(`length ${text.length} outside band ${input.length_band} (${lo}-${hi})`);
  }

  // 2. banned phrases
  for (const b of input.banned) {
    if (b.scope !== 'all' && b.scope !== 'opener' && b.scope !== input.tone) continue;
    const target = b.scope === 'opener' ? text.slice(0, 60) : text;
    let re;
    try { re = new RegExp(b.pattern, 'iu'); } catch { continue; }
    if (re.test(target)) reasons.push(`banned phrase: ${b.pattern}`);
  }

  // 3. emoji policy
  const emojis = text.match(EMOJI_RE) ?? [];
  const emojiCap = ['deadpan', 'minimal'].includes(input.tone) ? 0 : (cfg.max_emoji ?? 2);
  if (emojis.length > emojiCap) reasons.push(`${emojis.length} emoji > cap ${emojiCap} for tone ${input.tone}`);

  // 4. hashtags
  const tags = text.match(/#\w+/g) ?? [];
  if (tags.length > 1) reasons.push('more than 1 hashtag');
  if (tags.length === 1 && Math.random() > (cfg.hashtag_probability ?? 0.4)) {
    text = text.replace(/\s*#\w+/g, '').trim();   // silently drop instead of failing
  }

  // 5. must contain at least one concrete product fact (number, unit, or a detail token)
  const hasNumber = /\d/.test(text);
  const hasDetail = (input.product_details ?? []).some(d => {
    const tok = String(d).toLowerCase().split(/\s+/).filter(w => w.length > 4);
    return tok.some(w => text.toLowerCase().includes(w));
  });
  if (!hasNumber && !hasDetail && input.sell_intensity !== '0') {
    reasons.push('no concrete product detail — will read generic');
  }

  // 5b. TEXT-ONLY posts are held to a higher bar. With no photo, a post carrying no concrete
  // detail is pure assertion, and assertion is what makes affiliate copy invisible.
  // This applies even at sell_intensity 0, unlike the rule above.
  if (input.media_type === 'TEXT') {
    if (!hasNumber && !hasDetail) {
      reasons.push('text-only post with no concrete detail — nothing anchors it');
    }
    // Referring to a picture that does not exist is the classic text-post failure.
    if (/\b(gambar|foto|fotonya|gambarnya|di atas|liat nih|lihat gambar|swipe|geser)\b/i.test(text)) {
      reasons.push('text-only post references an image that does not exist');
    }
    if (text.length < 90) {
      reasons.push('text-only post too short to hold attention without a visual');
    }
  }

  // 5c. Posts WITH an image should not narrate the image — the reader can already see it.
  if (input.media_type !== 'TEXT' && /\b(di (gambar|foto) (ini|itu)|seperti (yang )?(terlihat|di gambar))\b/i.test(text)) {
    reasons.push('narrates the attached image instead of adding to it');
  }

  // 6. must not open with the product name
  if (input.product_name) {
    const first = text.slice(0, input.product_name.length + 4).toLowerCase();
    if (first.startsWith(input.product_name.toLowerCase().slice(0, 12))) {
      reasons.push('opens with product name');
    }
  }

  // 6b. SHOUTING — from the Malay headline books, which are built on ALL CAPS because they
  // targeted 2015 Facebook ads. On a text feed capitals are the clearest ad signal there is.
  // This lives here, not in banned_phrases, because that table is matched case-INsensitively
  // in Postgres, where [A-Z] would also match lowercase and reject ordinary copy.
  const shout = (text.match(/\b[A-Z]{4,}\b/g) ?? [])
    .filter(w => !/^(RM|OK|USB|LED|PDF|XL|XXL|COD|DIY|FYI)$/.test(w));
  if (shout.length >= 3) reasons.push(`${shout.length} ALL-CAPS words — reads as an ad`);
  const words = text.split(/\s+/).filter(Boolean);
  if (words.length >= 8 && shout.length / words.length > 0.25) {
    reasons.push('more than a quarter of the post is shouting');
  }

  // 7. structural AI tells
  if ((text.match(/—/g) ?? []).length >= 2) reasons.push('em-dash chain');
  if (/^\s*[-*•]\s/m.test(text) && input.length_band !== 'long') reasons.push('bullet list');
  if (/\?\s*$/.test(text) && /^\s*\w+.*\?/.test(text.split('\n')[0])) {
    // opens with a question AND closes with a question = classic engagement-bait shape
    reasons.push('question sandwich');
  }
  if (/(\b\w+\b)(\s+\1\b){2,}/i.test(text)) reasons.push('word repetition');

  // 8. sell intensity compliance
  const salesWords = /(beli|checkout|order|co\b|klik|link di|swipe|keranjang)/i;
  if (input.sell_intensity === '0' && salesWords.test(text)) reasons.push('sell words in intensity-0 post');

  // 9. anti-repetition vs last 30 posts
  let maxSim = 0, maxShingle = 0;
  for (const r of input.recent ?? []) {
    maxSim = Math.max(maxSim, cosine(input.embedding, r.embedding));
    maxShingle = Math.max(maxShingle, shingleOverlap(text, r.body));
  }
  if (maxSim > (cfg.max_similarity ?? 0.86)) reasons.push(`too similar to a recent post (cos ${maxSim.toFixed(3)})`);
  if (maxShingle > 0.18) reasons.push(`reuses phrasing skeleton (3-gram overlap ${maxShingle.toFixed(3)})`);

  // 10. opener uniqueness — first 5 words must not have been used in the last 30 posts
  const opener = t => t.toLowerCase().split(/\s+/).slice(0, 5).join(' ');
  if ((input.recent ?? []).some(r => opener(r.body) === opener(text))) reasons.push('duplicate opener');

  return {
    pass: reasons.length === 0,
    reasons,
    cleaned: text,
    stats: {
      media_type: input.media_type ?? 'IMAGE',
      chars: text.length,
      emoji: emojis.length,
      hashtag: (text.match(/#\w+/g) ?? []).length > 0,
      max_similarity: maxSim,
      max_shingle: maxShingle,
    },
  };
}

return [{ json: qa($json) }];
